import logging
import re

from taf.hw.rf_attenuator.devices.topyoung.topyoung import TopYoung
from taf.hw.rf_attenuator.exceptions import AttenuationReadError


class TopYoungTAS16T16511201NDEJS(TopYoung):
    _DB_REGEX = r'(\d*\.{0,1}\d*\s*)dB'
    _SET_CMD = "SA{} {}"
    _READ_CMD = 'RA{}'
    _CMD_ERR = 'Error'
    _SET_MULTIPLE_PORT_COMMAND = "SMA {}"

    def _verify_read_attenuation_command_response(self, rf_port_address, res):
        self._check_if_command_error(self._CMD_ERR, res)
        re_out = re.search(self._DB_REGEX, res)
        if re_out:
            value_read = re_out.groups()[0]
            logging.info('Channel {} attenuation value is {} dB.'.format(rf_port_address, value_read))
            return int(float(value_read))
        raise AttenuationReadError

    def _verify_set_attenuation_command_response(self, rf_port_address, res):
        self._check_if_command_error(self._CMD_ERR, res)

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        dictionary = dict(zip(rf_port_addresses, attenuation_values_db))
        set_command = ",".join(["{} {}".format(port, value) for port, value in dictionary.items()])
        cmd = self._SET_MULTIPLE_PORT_COMMAND.format(set_command)
        self._write_and_read(cmd)
        return cmd
